const input = Array.isArray($json) ? $json : [$json];
const rows = input.map((call) => {
  const text = `${call.voicemailText ?? ''}`.toLowerCase();
  const damage = ['hail', 'storm', 'shingles', 'water', 'dripping', 'leak'].some((term) => text.includes(term));
  const repeat = call.repeatCaller ? 2 : 0;
  const priorityScore = (damage ? 3 : 0) + repeat;
  return { ...call, priorityScore, queue: priorityScore >= 4 ? 'call-now' : 'next-office-block' };
});
return rows.sort((a, b) => b.priorityScore - a.priorityScore).map((row) => ({ json: row }));
